@page "/apply"
@using sv_eecffa7134bb4e3bbe1e5dddc9aef4f0.Models
@using sv_eecffa7134bb4e3bbe1e5dddc9aef4f0.Services
@rendermode InteractiveServer

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 1:
            <PersonalInfoStep @ref="personalInfoStep"
                              Model="personalInfo"
                              OnNext="AdvanceStep"
                              OnValidateEmail="ValidateEmail" />
            break;

        case 2:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="AdvanceStep"
                             OnBack="PreviousStep" />
            break;

        case 3:
            <ReferencesStep References="references"
                            OnNext="AdvanceStep"
                            OnBack="PreviousStep" />
            break;

        case 4:
            <CoverLetterStep CoverLetter="@coverLetter"
                             CoverLetterChanged="(val) => coverLetter = val"
                             OnNext="AdvanceStep"
                             OnBack="PreviousStep" />
            break;

        case 5:
            <ReviewStep Personal="personalInfo"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="@coverLetter"
                        IsSubmitted="isSubmitted"
                        ApplicationId="applicationId"
                        OnBack="PreviousStep"
                        OnEditSection="GoToStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep = 1;
    private PersonalInfoStep? personalInfoStep;

    // Form state
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
    private string coverLetter = "";

    // Submission state
    private bool isSubmitted;
    private int applicationId;

    private void AdvanceStep()
    {
        if (currentStep < 5) currentStep++;
    }

    private void PreviousStep()
    {
        if (currentStep > 1) currentStep--;
    }

    private void GoToStep(int step)
    {
        if (step >= 1 && step <= 5)
        {
            currentStep = step;
        }
    }

    private async Task ValidateEmail(string? email)
    {
        if (string.IsNullOrWhiteSpace(email)) return;

        var isValid = await ApplicationService.ValidateEmailAsync(email);
        if (!isValid)
        {
            personalInfoStep?.SetError("The email address is not valid. Please check and try again.");
        }
        else
        {
            AdvanceStep();
        }
    }

    private async Task SubmitApplication()
    {
        var application = new JobApplication(
            personalInfo.ToRecord(),
            new WorkHistory(workEntries.Select(e => e.ToRecord()).ToList()),
            references.Select(r => r.ToRecord()).ToList(),
            coverLetter
        );

        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitted = true;
    }
}

@namespace sv_eecffa7134bb4e3bbe1e5dddc9aef4f0.Components.Pages.JobApplication

<nav aria-label="Application progress" class="step-indicator mb-4">
    <ol class="d-flex list-unstyled justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var isCompleted = step < CurrentStep;
            var isCurrent = step == CurrentStep;
            var isFuture = step > CurrentStep;

            <li class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
                @onclick="() => OnStepClick(step)"
                role="button"
                style="cursor: @(isCompleted ? "pointer" : "default")">
                <div class="step-circle mx-auto mb-1 rounded-circle d-flex align-items-center justify-content-center
                    @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light text-muted border")"
                     style="width:36px;height:36px;">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </div>
                <small class="@(isFuture ? "text-muted" : isCurrent ? "fw-bold text-primary" : "text-success")">
                    @StepNames[i]
                </small>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

