@page "/apply"
@using sv_eecffa7134bb4e3bbe1e5dddc9aef4f0.Models
@using sv_eecffa7134bb4e3bbe1e5dddc9aef4f0.Services
@rendermode InteractiveServer

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 1:
            <PersonalInfoStep @ref="personalInfoStep"
                              Model="personalInfo"
                              OnNext="AdvanceStep"
                              OnValidateEmail="ValidateEmail" />
            break;

        case 2:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="AdvanceStep"
                             OnBack="PreviousStep" />
            break;

        case 3:
            <ReferencesStep References="references"
                            OnNext="AdvanceStep"
                            OnBack="PreviousStep" />
            break;

        case 4:
            <CoverLetterStep CoverLetter="@coverLetter"
                             CoverLetterChanged="(val) => coverLetter = val"
                             OnNext="AdvanceStep"
                             OnBack="PreviousStep" />
            break;

        case 5:
            <ReviewStep Personal="personalInfo"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="@coverLetter"
                        IsSubmitted="isSubmitted"
                        ApplicationId="applicationId"
                        OnBack="PreviousStep"
                        OnEditSection="GoToStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep = 1;
    private PersonalInfoStep? personalInfoStep;

    // Form state
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
    private string coverLetter = "";

    // Submission state
    private bool isSubmitted;
    private int applicationId;

    private void AdvanceStep()
    {
        if (currentStep < 5) currentStep++;
    }

    private void PreviousStep()
    {
        if (currentStep > 1) currentStep--;
    }

    private void GoToStep(int step)
    {
        if (step >= 1 && step <= 5)
        {
            currentStep = step;
        }
    }

    private async Task ValidateEmail(string? email)
    {
        if (string.IsNullOrWhiteSpace(email)) return;

        var isValid = await ApplicationService.ValidateEmailAsync(email);
        if (!isValid)
        {
            personalInfoStep?.SetError("The email address is not valid. Please check and try again.");
        }
        else
        {
            AdvanceStep();
        }
    }

    private async Task SubmitApplication()
    {
        var application = new JobApplication(
            personalInfo.ToRecord(),
            new WorkHistory(workEntries.Select(e => e.ToRecord()).ToList()),
            references.Select(r => r.ToRecord()).ToList(),
            coverLetter
        );

        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitted = true;
    }
}

