@namespace sv_eecffa7134bb4e3bbe1e5dddc9aef4f0.Components.Pages.JobApplication

<h4 class="mb-3">Cover Letter</h4>

<div class="mb-3">
    <label class="form-label">Write your cover letter</label>
    <textarea class="form-control" rows="12" maxlength="@MaxLength"
              @bind="coverLetterValue" @bind:event="oninput"
              placeholder="Tell us why you're a great fit for this role..."></textarea>
    <div class="form-text text-end">
        @coverLetterValue.Length / @MaxLength characters
    </div>
</div>

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string coverLetterValue = "";

    protected override void OnParametersSet()
    {
        coverLetterValue = CoverLetter;
    }

    private async Task HandleNext()
    {
        await CoverLetterChanged.InvokeAsync(coverLetterValue);
        await OnNext.InvokeAsync();
    }
}

